"use client";

import { useState, useEffect } from "react";import {
  User,
  CheckCircle2,
  X,
  ExternalLink,
  ChevronDown,
  ChevronUp,
  Sparkles,
  Lock,
  AtSign,
} from "lucide-react";

const STORAGE_KEY = "instapulse_profile_username";

export interface ProfileContext {
  username: string;
  setAt: string;
}

interface ProfileLoginProps {
  onProfileSet: (profile: ProfileContext | null) => void;
  currentProfile: ProfileContext | null;
}

export default function ProfileLogin({ onProfileSet, currentProfile }: ProfileLoginProps) {
  const [isExpanded, setIsExpanded] = useState(false);
  // Lazy initializer — reads localStorage synchronously, no setState-in-effect
  const [inputValue, setInputValue] = useState(() => {
    if (typeof window === "undefined") return "";
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        const parsed: ProfileContext = JSON.parse(stored);
        return parsed.username;
      }
    } catch { /* ignore */ }
    return "";
  });
  const [error, setError] = useState<string | null>(null);

  // Notify parent of persisted profile once on mount (synchronously from localStorage)
  useEffect(() => {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        const parsed: ProfileContext = JSON.parse(stored);
        onProfileSet(parsed);
      }
    } catch { /* ignore */ }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []); // intentionally empty — only run once on mount

  const handleSet = () => {
    const clean = inputValue.trim().replace(/^@/, "").toLowerCase();
    if (!clean) {
      setError("Please enter a username.");
      return;
    }
    if (!/^[a-z0-9_.]{1,30}$/.test(clean)) {
      setError("Invalid username format (only letters, numbers, _ and .)");
      return;
    }
    const profile: ProfileContext = { username: clean, setAt: new Date().toISOString() };
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(profile));
    } catch {
      /* ignore */
    }
    onProfileSet(profile);
    setError(null);
    setIsExpanded(false);
  };

  const handleClear = () => {
    try {
      localStorage.removeItem(STORAGE_KEY);
    } catch {
      /* ignore */
    }
    onProfileSet(null);
    setInputValue("");
    setError(null);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter") handleSet();
    if (e.key === "Escape") setIsExpanded(false);
  };

  return (
    <div className="card-clean overflow-hidden">
      {/* Header toggle */}
      <button
        onClick={() => setIsExpanded(!isExpanded)}
        className="w-full flex items-center justify-between p-4 sm:p-5 text-left cursor-pointer hover:bg-zinc-50/50 dark:hover:bg-white/[0.02] transition-colors"
      >
        <div className="flex items-center gap-2.5">
          {currentProfile ? (
            <div className="w-7 h-7 rounded-full bg-gradient-to-tr from-[#833ab4] via-[#fd1d1d] to-[#fcb045] flex items-center justify-center">
              <span className="text-white text-xs font-bold uppercase">
                {currentProfile.username[0]}
              </span>
            </div>
          ) : (
            <div className="w-7 h-7 rounded-full bg-zinc-100 dark:bg-zinc-800 flex items-center justify-center">
              <User className="w-3.5 h-3.5 text-zinc-400" />
            </div>
          )}
          <div className="text-left">
            <span className="text-xs sm:text-sm font-semibold text-zinc-800 dark:text-zinc-200 block">
              {currentProfile ? `@${currentProfile.username}` : "Set your Instagram ID"}
            </span>
            {currentProfile && (
              <span className="text-[10px] text-zinc-400">
                Profile linked — viewing your data
              </span>
            )}
            {!currentProfile && (
              <span className="text-[10px] text-zinc-400">
                Optional · links your profile for personalized insights
              </span>
            )}
          </div>
        </div>
        <div className="flex items-center gap-2">
          {currentProfile && (
            <span className="hidden sm:flex items-center gap-1 text-[10px] px-2 py-0.5 rounded-full bg-emerald-50 dark:bg-emerald-950/40 text-emerald-700 dark:text-emerald-400 border border-emerald-200/60 dark:border-emerald-900/40 font-medium">
              <CheckCircle2 className="w-3 h-3" />
              Linked
            </span>
          )}
          {isExpanded ? <ChevronUp className="w-4 h-4 text-zinc-400" /> : <ChevronDown className="w-4 h-4 text-zinc-400" />}
        </div>
      </button>

      {isExpanded && (
        <div className="px-4 pb-5 sm:px-5 sm:pb-6 border-t border-zinc-100 dark:border-white/[0.04] pt-4 space-y-4">
          {/* Privacy notice */}
          <div className="flex items-start gap-2 p-3 rounded-lg bg-emerald-50 dark:bg-emerald-950/30 border border-emerald-200/60 dark:border-emerald-900/40">
            <Lock className="w-3.5 h-3.5 text-emerald-600 dark:text-emerald-400 mt-0.5 shrink-0" />
            <p className="text-[11px] text-emerald-700 dark:text-emerald-300 leading-relaxed">
              <strong>100% private.</strong> Your username is only stored in your browser&apos;s localStorage. It is never sent to any server. No password required — this is just for displaying your profile header and linking your uploaded data.
            </p>
          </div>

          {/* Input */}
          <div className="space-y-2">
            <label className="text-xs font-semibold text-zinc-700 dark:text-zinc-300">
              Your Instagram Username
            </label>
            <div className="relative">
              <div className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-400">
                <AtSign className="w-4 h-4" />
              </div>
              <input
                type="text"
                value={inputValue}
                onChange={(e) => { setInputValue(e.target.value); setError(null); }}
                onKeyDown={handleKeyDown}
                placeholder="yourinstagramhandle"
                maxLength={30}
                className="w-full pl-9 pr-4 py-2.5 text-sm rounded-xl border border-zinc-200 dark:border-zinc-700/80 bg-zinc-50 dark:bg-zinc-800/50 text-zinc-900 dark:text-zinc-100 placeholder-zinc-400 focus:outline-none focus:ring-2 focus:ring-purple-500/50 focus:border-purple-400 transition-all"
              />
            </div>
            {error && (
              <p className="text-[11px] text-rose-600 dark:text-rose-400 flex items-center gap-1">
                <X className="w-3 h-3" /> {error}
              </p>
            )}
          </div>

          {/* Actions */}
          <div className="flex items-center gap-2">
            <button
              onClick={handleSet}
              className="flex items-center gap-1.5 px-4 py-2 rounded-xl text-xs font-semibold bg-zinc-900 hover:bg-zinc-800 text-white dark:bg-white dark:text-zinc-900 dark:hover:bg-zinc-100 transition-colors"
            >
              <CheckCircle2 className="w-3.5 h-3.5" />
              {currentProfile ? "Update" : "Set Profile"}
            </button>

            {currentProfile && (
              <button
                onClick={handleClear}
                className="flex items-center gap-1.5 px-4 py-2 rounded-xl text-xs font-semibold text-zinc-600 dark:text-zinc-400 border border-zinc-200 dark:border-zinc-700 hover:bg-zinc-100 dark:hover:bg-zinc-800 transition-colors"
              >
                <X className="w-3.5 h-3.5" />
                Remove
              </button>
            )}

            {currentProfile && (
              <a
                href={`https://www.instagram.com/${currentProfile.username}/`}
                target="_blank"
                rel="noopener noreferrer"
                className="ml-auto flex items-center gap-1.5 px-3 py-2 rounded-xl text-xs font-semibold text-zinc-500 dark:text-zinc-400 hover:text-zinc-800 dark:hover:text-zinc-200 transition-colors"
              >
                <ExternalLink className="w-3.5 h-3.5" />
                View on Instagram
              </a>
            )}
          </div>

          {/* Current profile card */}
          {currentProfile && (
            <div className="flex items-center gap-3 p-3 rounded-xl border border-zinc-200/60 dark:border-white/[0.06] bg-zinc-50/50 dark:bg-white/[0.01]">
              <div className="w-10 h-10 rounded-full bg-gradient-to-tr from-[#833ab4] via-[#fd1d1d] to-[#fcb045] flex items-center justify-center shrink-0">
                <span className="text-white text-sm font-bold uppercase">
                  {currentProfile.username[0]}
                </span>
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-1.5">
                  <span className="text-sm font-bold text-zinc-900 dark:text-zinc-100 truncate">
                    @{currentProfile.username}
                  </span>
                  <Sparkles className="w-3.5 h-3.5 text-pink-500 shrink-0" />
                </div>
                <p className="text-[10px] text-zinc-400 mt-0.5">
                  Linked {new Date(currentProfile.setAt).toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" })}
                </p>
              </div>
              <a
                href={`https://www.instagram.com/${currentProfile.username}/`}
                target="_blank"
                rel="noopener noreferrer"
                className="shrink-0 p-1.5 rounded-lg hover:bg-zinc-100 dark:hover:bg-zinc-800 transition-colors"
                title="Open Instagram profile"
              >
                <ExternalLink className="w-3.5 h-3.5 text-zinc-400" />
              </a>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export function useProfileContext(): [ProfileContext | null, (p: ProfileContext | null) => void] {
  const [profile, setProfile] = useState<ProfileContext | null>(null);
  return [profile, setProfile];
}

