"use client";

import { Users, UserCheck, Heart, UserX } from "lucide-react";
import { motion } from "framer-motion";

interface KpiCardsProps {
  followersCount: number;
  followingCount: number;
  mutualsCount: number;
  dontFollowBackCount: number;
}

export default function KpiCards({
  followersCount,
  followingCount,
  mutualsCount,
  dontFollowBackCount,
}: KpiCardsProps) {
  const mutualRatio = followingCount > 0 ? Math.round((mutualsCount / followingCount) * 100) : 0;
  const unreciprocatedRatio = followingCount > 0 ? Math.round((dontFollowBackCount / followingCount) * 100) : 0;

  const cards = [
    {
      label: "Followers",
      value: followersCount,
      icon: Users,
      badge: "In your network",
      badgeColor: "text-zinc-500 bg-zinc-100 dark:bg-zinc-800",
    },
    {
      label: "Following",
      value: followingCount,
      icon: UserCheck,
      badge: "Accounts followed",
      badgeColor: "text-zinc-500 bg-zinc-100 dark:bg-zinc-800",
    },
    {
      label: "Mutuals",
      value: mutualsCount,
      icon: Heart,
      badge: `${mutualRatio}% follow back`,
      badgeColor: "text-emerald-700 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-950/40",
    },
    {
      label: "Don't Follow Back",
      value: dontFollowBackCount,
      icon: UserX,
      badge: `${unreciprocatedRatio}% unreciprocated`,
      badgeColor: "text-rose-700 dark:text-rose-400 bg-rose-50 dark:bg-rose-950/40",
    },
  ];

  return (
    <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
      {cards.map((card, i) => {
        const Icon = card.icon;
        return (
          <motion.div
            key={card.label}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: i * 0.04 }}
            className="card-clean p-4 sm:p-5 flex flex-col justify-between"
          >
            <div className="flex items-center justify-between">
              <span className="text-xs font-medium text-zinc-500 dark:text-zinc-400">
                {card.label}
              </span>
              <div className="w-8 h-8 rounded-lg bg-zinc-100 dark:bg-zinc-800/80 flex items-center justify-center text-zinc-600 dark:text-zinc-300">
                <Icon className="w-4 h-4" />
              </div>
            </div>

            <div className="mt-4">
              <div className="text-2xl sm:text-3xl font-bold tracking-tight text-zinc-900 dark:text-white tabular-nums">
                {card.value.toLocaleString()}
              </div>
              <div className="mt-2">
                <span
                  className={`inline-block text-[11px] font-medium px-2 py-0.5 rounded-md ${card.badgeColor}`}
                >
                  {card.badge}
                </span>
              </div>
            </div>
          </motion.div>
        );
      })}
    </div>
  );
}
