"use client";

import { useState, useEffect, useCallback } from "react";
import Navbar from "@/components/Navbar";
import OnboardingGuide from "@/components/OnboardingGuide";
import DropZone from "@/components/DropZone";
import Dashboard from "@/components/Dashboard";
import ProfileLogin from "@/components/ProfileLogin";
import { computeRelationships } from "@/lib/computeSets";
import { saveSnapshot, getAllSnapshots, getSnapshot } from "@/lib/storage";
import { parseInstagramZip } from "@/lib/zipParser";
import { useTheme } from "@/hooks/useTheme";
import type { InstagramData, RelationshipSets, Snapshot } from "@/lib/types";
import type { ProfileContext } from "@/components/ProfileLogin";
import { ShieldCheck, Lock, Zap, ArrowRight, Loader2 } from "lucide-react";

export default function Home() {
  useTheme();

  const [data, setData] = useState<InstagramData | null>(null);
  const [relationships, setRelationships] = useState<RelationshipSets | null>(null);
  const [currentSnapshot, setCurrentSnapshot] = useState<Snapshot | undefined>(undefined);
  const [snapshots, setSnapshots] = useState<Snapshot[]>([]);
  const [selectedSnapshotId, setSelectedSnapshotId] = useState<number | null>(null);
  const [isLoadingSample, setIsLoadingSample] = useState(false);
  const [sampleError, setSampleError] = useState<string | null>(null);
  const [profile, setProfile] = useState<ProfileContext | null>(null);

  // Load snapshots from IndexedDB
  const refreshSnapshots = useCallback(async () => {
    try {
      const all = await getAllSnapshots();
      setSnapshots(all);
    } catch (e) {
      console.warn("IndexedDB load error:", e);
    }
  }, []);

  useEffect(() => {
    // Load snapshots once on mount
    getAllSnapshots()
      .then(setSnapshots)
      .catch((e) => console.warn("IndexedDB load error:", e));
  }, []);

  // Handle parsed data
  const handleDataParsed = useCallback(
    async (parsedData: InstagramData, customLabel?: string) => {
      const rels = computeRelationships(parsedData);
      setData(parsedData);
      setRelationships(rels);
      setSelectedSnapshotId(null);

      try {
        const followersMap: Record<string, typeof parsedData.followers[0]> = {};
        const followingMap: Record<string, typeof parsedData.following[0]> = {};
        for (const u of parsedData.followers) followersMap[u.username] = u;
        for (const u of parsedData.following) followingMap[u.username] = u;

        const newSnapshot: Omit<Snapshot, "id"> = {
          date: new Date().toISOString(),
          label:
            customLabel ||
            `Export (${new Date().toLocaleDateString(undefined, {
              month: "short",
              day: "numeric",
              year: "numeric",
            })})`,
          followersMap,
          followingMap,
          stats: {
            followersCount: parsedData.followers.length,
            followingCount: parsedData.following.length,
            mutualsCount: rels.mutuals.length,
            dontFollowBackCount: rels.dontFollowBack.length,
            fansCount: rels.fans.length,
          },
        };

        const id = await saveSnapshot(newSnapshot);
        const saved = { ...newSnapshot, id };
        setCurrentSnapshot(saved);
        await refreshSnapshots();
      } catch (err) {
        console.warn("Failed to persist snapshot:", err);
      }
    },
    [refreshSnapshots]
  );

  // Snapshot selection
  const handleSelectSnapshot = useCallback(
    async (id: number | null) => {
      setSelectedSnapshotId(id);
      if (id === null) return;

      try {
        const snap = await getSnapshot(id);
        if (snap) {
          setCurrentSnapshot(snap);
          const followers = Object.values(snap.followersMap);
          const following = Object.values(snap.followingMap);
          const reconstructedData: InstagramData = {
            followers,
            following,
            pendingRequests: data?.pendingRequests || [],
            recentlyUnfollowed: data?.recentlyUnfollowed || [],
            closeFriends: data?.closeFriends || [],
            restrictedProfiles: data?.restrictedProfiles || [],
          };
          setData(reconstructedData);
          setRelationships(computeRelationships(reconstructedData));
        }
      } catch (err) {
        console.warn("Failed to load historical snapshot:", err);
      }
    },
    [data]
  );

  // Reset
  const handleReset = useCallback(() => {
    setData(null);
    setRelationships(null);
    setCurrentSnapshot(undefined);
    setSelectedSnapshotId(null);
    setSampleError(null);
  }, []);

  // One-click load real export
  const handleLoadSample = async () => {
    setIsLoadingSample(true);
    setSampleError(null);
    try {
      const response = await fetch("/sample-export.zip");
      if (!response.ok) {
        throw new Error("Could not load sample file.");
      }
      const blob = await response.blob();
      const file = new File([blob], "instagram-iarmaandeepsingh-2026-10-28-GqULFReW.zip", {
        type: "application/zip",
      });
      const parsed = await parseInstagramZip(file);
      await handleDataParsed(parsed, "Real Export (176 followers • 264 following)");
    } catch (err) {
      setSampleError(err instanceof Error ? err.message : "Failed to load sample export");
    } finally {
      setIsLoadingSample(false);
    }
  };

  return (
    <div className="min-h-screen flex flex-col">
      <Navbar
        snapshots={snapshots}
        selectedSnapshotId={selectedSnapshotId}
        onSelectSnapshot={handleSelectSnapshot}
        hasData={Boolean(data && relationships)}
        onReset={handleReset}
      />

      <main className="flex-1 max-w-6xl w-full mx-auto px-4 sm:px-6 py-8 sm:py-12">
        {data && relationships ? (
          <Dashboard
            data={data}
            relationships={relationships}
            currentSnapshot={currentSnapshot}
            onReset={handleReset}
            profile={profile}
          />
        ) : (
          <div className="max-w-2xl mx-auto space-y-8 animate-in fade-in duration-300">
            {/* Hero Section */}
            <div className="text-center space-y-3 pt-4 sm:pt-8">
              <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold bg-zinc-100 dark:bg-zinc-800/80 text-zinc-700 dark:text-zinc-300 border border-zinc-200/80 dark:border-white/[0.08]">
                <ShieldCheck className="w-3.5 h-3.5 text-emerald-600 dark:text-emerald-400" />
                <span>Zero Logins Required • Zero Account Risk</span>
              </div>

              <h1 className="text-3xl sm:text-4xl lg:text-5xl font-extrabold tracking-tight text-zinc-900 dark:text-white">
                Find Out Who <span className="gradient-text">Doesn&apos;t Follow Back</span>
              </h1>

              <p className="text-sm sm:text-base text-zinc-500 dark:text-zinc-400 max-w-lg mx-auto leading-relaxed">
                Upload your official Instagram JSON data export. Everything is extracted and computed strictly within your browser&apos;s memory.
              </p>
            </div>

            {/* Profile Login */}
            <ProfileLogin onProfileSet={setProfile} currentProfile={profile} />

            {/* Upload Box */}
            <div className="card-clean p-5 sm:p-6 space-y-4">
              <DropZone onDataParsed={handleDataParsed} />

              {/* Discreet One-Click Test Option */}
              <div className="pt-2 border-t border-zinc-100 dark:border-white/[0.04] flex flex-col sm:flex-row items-center justify-between gap-3 text-xs">
                <div className="text-zinc-500 dark:text-zinc-400 text-center sm:text-left">
                  <span className="font-medium text-zinc-800 dark:text-zinc-200">
                    Want to test right now?
                  </span>{" "}
                  <span>Use your real export file (176 followers • 264 following)</span>
                </div>

                <button
                  onClick={handleLoadSample}
                  disabled={isLoadingSample}
                  className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold bg-zinc-900 hover:bg-zinc-800 text-white dark:bg-white dark:text-zinc-900 dark:hover:bg-zinc-100 transition-colors shrink-0 disabled:opacity-50 cursor-pointer"
                  id="load-sample-export-btn"
                >
                  {isLoadingSample ? (
                    <>
                      <Loader2 className="w-3 h-3 animate-spin" />
                      <span>Parsing...</span>
                    </>
                  ) : (
                    <>
                      <span>Load Real Data</span>
                      <ArrowRight className="w-3 h-3" />
                    </>
                  )}
                </button>
              </div>

              {sampleError && (
                <p className="text-xs text-rose-600 dark:text-rose-400 text-center pt-1">
                  {sampleError}
                </p>
              )}
            </div>

            {/* Collapsible Export Guide */}
            <OnboardingGuide />

            {/* 3 Privacy & Feature Pillars */}
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 pt-2">
              <div className="p-4 rounded-xl border border-zinc-200/70 dark:border-white/[0.06] bg-white/40 dark:bg-white/[0.01]">
                <ShieldCheck className="w-4 h-4 text-emerald-600 dark:text-emerald-400 mb-2" />
                <h4 className="text-xs font-bold text-zinc-900 dark:text-zinc-100">
                  No Credentials
                </h4>
                <p className="text-[11px] text-zinc-500 dark:text-zinc-400 mt-1 leading-relaxed">
                  Never enter passwords or 2FA. Completely safe from Instagram shadowbans.
                </p>
              </div>

              <div className="p-4 rounded-xl border border-zinc-200/70 dark:border-white/[0.06] bg-white/40 dark:bg-white/[0.01]">
                <Lock className="w-4 h-4 text-purple-600 dark:text-purple-400 mb-2" />
                <h4 className="text-xs font-bold text-zinc-900 dark:text-zinc-100">
                  Client-Side Only
                </h4>
                <p className="text-[11px] text-zinc-500 dark:text-zinc-400 mt-1 leading-relaxed">
                  ZIP extraction and Set operations happen 100% in your local browser memory.
                </p>
              </div>

              <div className="p-4 rounded-xl border border-zinc-200/70 dark:border-white/[0.06] bg-white/40 dark:bg-white/[0.01]">
                <Zap className="w-4 h-4 text-amber-500 mb-2" />
                <h4 className="text-xs font-bold text-zinc-900 dark:text-zinc-100">
                  Historical Diffs
                </h4>
                <p className="text-[11px] text-zinc-500 dark:text-zinc-400 mt-1 leading-relaxed">
                  Snapshots store locally in IndexedDB so you can see who unfollowed over time.
                </p>
              </div>
            </div>
          </div>
        )}
      </main>

      {/* Clean Minimal Footer */}
      <footer className="border-t border-zinc-200/60 dark:border-white/[0.06] py-5 text-center text-xs text-zinc-400">
        <p>InstaPulse • 100% Local Privacy-First Analytics • Not affiliated with Meta or Instagram</p>
      </footer>
    </div>
  );
}
